import type { MetadataRoute } from "next";

// Makes calAI installable ("Add to Home Screen"). Icons are generated by
// scripts/generate-icons.mjs.
export default function manifest(): MetadataRoute.Manifest {
  return {
    name: "calAI",
    short_name: "calAI",
    description: "Snap a photo of your meal and log calories and macros in seconds.",
    start_url: "/today",
    scope: "/",
    display: "standalone",
    orientation: "portrait",
    background_color: "#f7f7f5",
    theme_color: "#059669",
    icons: [
      { src: "/icons/icon-192.png", sizes: "192x192", type: "image/png", purpose: "any" },
      { src: "/icons/icon-512.png", sizes: "512x512", type: "image/png", purpose: "any" },
      {
        src: "/icons/icon-maskable-512.png",
        sizes: "512x512",
        type: "image/png",
        purpose: "maskable",
      },
    ],
    shortcuts: [
      { name: "Snap a meal", url: "/log/photo" },
      { name: "Enter a meal manually", url: "/log/manual" },
    ],
  };
}
